import java.util.*;

class Solution {
    public List<List<Integer>> findRLEArray(int[][] encoded1, int[][] encoded2) {
        int i = 0, j = 0;
        int val1 = encoded1[0][0], cnt1 = encoded1[0][1];
        int val2 = encoded2[0][0], cnt2 = encoded2[0][1];
        List<List<Integer>> ans = new ArrayList<>();

        while (i < encoded1.length && j < encoded2.length) {
            int take = Math.min(cnt1, cnt2);
            int prod = val1 * val2;

            if (!ans.isEmpty() && ans.get(ans.size() - 1).get(0) == prod) {
                int lastIdx = ans.size() - 1;
                ans.get(lastIdx).set(1, ans.get(lastIdx).get(1) + take);
            } else {
                ans.add(new ArrayList<>(Arrays.asList(prod, take)));
            }

            cnt1 -= take;
            cnt2 -= take;

            if (cnt1 == 0) {
                i++;
                if (i < encoded1.length) {
                    val1 = encoded1[i][0];
                    cnt1 = encoded1[i][1];
                }
            }
            if (cnt2 == 0) {
                j++;
                if (j < encoded2.length) {
                    val2 = encoded2[j][0];
                    cnt2 = encoded2[j][1];
                }
            }
        }
        return ans;
    }
}

/**
 * @param {number[][]} encoded1
 * @param {number[][]} encoded2
 * @return {number[][]}
 */
var findRLEArray = function(encoded1, encoded2) {
    let i = 0, j = 0;
    let [val1, cnt1] = encoded1[0];
    let [val2, cnt2] = encoded2[0];
    const ans = [];

    while (i < encoded1.length && j < encoded2.length) {
        const take = Math.min(cnt1, cnt2);
        const prod = val1 * val2;

        if (ans.length > 0 && ans[ans.length - 1][0] === prod) {
            ans[ans.length - 1][1] += take;
        } else {
            ans.push([prod, take]);
        }

        cnt1 -= take;
        cnt2 -= take;

        if (cnt1 === 0) {
            i++;
            if (i < encoded1.length) [val1, cnt1] = encoded1[i];
        }
        if (cnt2 === 0) {
            j++;
            if (j < encoded2.length) [val2, cnt2] = encoded2[j];
        }
    }
    return ans;
};
